const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')

const source = fs.readFileSync(path.join(__dirname, '..', 'app/orcamento-rapido/page.tsx'), 'utf8')
const footer = source.match(/<div className="fixed inset-x-0 bottom-\[calc\(3\.6rem\+env\(safe-area-inset-bottom\)\)\][\s\S]*?(?=\{resumo && <div)/)?.[0]
assert.ok(footer, 'Barra fixa da coleta deve existir')
assert.match(footer, /onClick=\{\(\) => void salvar\(\)\}/, 'Botão de envio abre a validação existente')
assert.match(footer, /'Enviar orçamento'/, 'Envio visível no pedido comum')
assert.match(footer, /'Salvar orçamento e continuar'/, 'Fluxo sob medida preservado')
assert.match(footer, /disabled=\{salvando\}/, 'Bloqueia novo clique durante o envio')
assert.match(footer, /onClick=\{\(\)=>setResumo\(true\)\}/, 'Resumo segue disponível')
assert.match(footer, /onClick=\{adicionar\}/, 'Adicionar item segue disponível')
assert.match(source, /async function salvar\(\) \{[\s\S]*?setConferenciaAberta\(true\)/, 'Envio mantém validação e conferência')
assert.match(source, /onClick=\{\(\) => void confirmarEnvio\(\)\}/, 'Confirmação final segue disponível')
assert.match(source, /const resultado = await criarOrcamentoNoServidor\(dadosForm\)/, 'Persistência original mantida')
assert.match(source, /pb-56 pt-5 sm:px-6 sm:pt-6 md:pb-28/, 'Conteúdo deve deixar espaço para o rodapé e a navegação móvel')
assert.match(footer, /md:bottom-0/, 'Em desktop o rodapé mantém posição original')
assert.match(footer, /grid-cols-2[\s\S]*?col-span-2/, 'Botão de envio ocupa linha inteira no celular')
assert.match(source, /resumo && <div className="fixed inset-0 z-\[70\]/, 'Resumo cobre a barra inferior geral')
assert.match(source, /sticky bottom-0 z-10 -mx-5/, 'Ações do resumo ficam acessíveis durante a rolagem')
assert.match(source, /conferenciaAberta &&[\s\S]*?grid shrink-0 grid-cols-2/, 'Confirmação não é escondida por rolagem no celular')
assert.match(source, /buscaClienteAberta&&<BuscaClientesComGestao/, 'Busca de clientes só abre enquanto o campo está ativo')
assert.match(source, /setBuscaClienteAberta\(false\)/, 'Busca de clientes fecha ao selecionar ou sair do campo')
assert.match(source, /buscaAberta&&!!resultados.length/, 'Resultados de produtos fecham ao mudar de campo')
assert.match(source, /setResultados\(\[\]\);setBuscaAberta\(false\)/, 'Seleção de produto não reabre sugestões')
const nav = fs.readFileSync(path.join(__dirname, '..', 'components/system/MobileNavigationControls.tsx'), 'utf8')
assert.match(nav, /bottom-0 z-\[60\]/, 'Navegação móvel geral continua presente')
console.log('OK: botão de envio visível; resumo, conferência e fluxo sob medida preservados')
